export const ALL_AGENT_TOOLS = [...new Set(PROJECT_PROFILES.flatMap((profile) => profile.tools))];

export function projectProfile(projectId) {
  return PROJECT_PROFILES.find((profile) => profile.projectId === projectId) || null;
}

export function toolsForProjectId(projectId) {
  if (!projectId || projectId === 'all') return ALL_AGENT_TOOLS;
  return projectProfile(projectId)?.tools || ['freeChat', 'RAG'];
}
